"""Generate the offline Dart catalogue from the reviewable isiZulu JSON source."""
import json
from pathlib import Path
root = Path(__file__).resolve().parents[1]
entries = json.loads((root / 'lib/app/localization/zu.json').read_text())
def dart_string(value):
    return json.dumps(value, ensure_ascii=False).replace('$', r'\$')
(root / 'lib/app/localization/catalog.dart').write_text(
    '// Generated by tool/generate_catalog.py. Edit zu.json then regenerate.\n'
    'const isiZuluCatalog = <String, String>{\n' +
    ''.join(f'  {dart_string(key)}: {dart_string(value)},\n' for key, value in entries.items()) + '};\n')
